import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_matvec_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
    int m = blockIdx.x;
    if (m >= M) return;

    int tid = threadIdx.x;
    int nthreads = blockDim.x;

    // CuTe tensors for the row of A and the vector B
    Tensor gA = make_tensor(make_gmem_ptr(A + (size_t)m * (size_t)K),
                             make_shape(K), make_stride(Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(B),
                             make_shape(K), make_stride(Int<1>{}));

    float sum = 0.f;

    // Vectorized main loop using float4 for coalesced, high-throughput loads
    int K4 = K / 4;
    const float4* A4 = reinterpret_cast<const float4*>(A + (size_t)m * (size_t)K);
    const float4* B4 = reinterpret_cast<const float4*>(B);

    for (int i = tid; i < K4; i += nthreads) {
        float4 a = A4[i];
        float4 b = B4[i];
        sum += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    }

    // Remainder elements (if K not divisible by 4), handled via CuTe tensor indexing
    for (int i = K4 * 4 + tid; i < K; i += nthreads) {
        sum += gA(i) * gB(i);
    }

    // Warp-level reduction
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
    }

    __shared__ float warp_sums[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;
    int nwarps = (nthreads + 31) >> 5;

    if (lane == 0) {
        warp_sums[warp_id] = sum;
    }
    __syncthreads();

    if (warp_id == 0) {
        float total = (lane < nwarps) ? warp_sums[lane] : 0.f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            total += __shfl_down_sync(0xffffffff, total, offset);
        }
        if (lane == 0) {
            C[m] = total;
        }
    }
}

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");

    int M = (int)A.size(0);
    int K = (int)A.size(1);
    TORCH_CHECK((int)B.size(0) == K, "B.size(0) must equal A.size(1)");

    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C = torch::empty({M, 1}, A.options());

    int threads = 256;
    dim3 block(threads);
    dim3 grid(M);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_matvec_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, K);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE matvec launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K).cuda()
    B = torch.rand(K, 1).cuda()
    return [A, B]


def get_init_inputs():
    return []

